{"command": "cd /tmp/sv-8862bc44c2fa4b57a882b3477ce6ae96/advanced-multi-complexity && python3 -c "
import json

with open('baseline-packages.json') as f:
    baseline = json.load(f)
with open('after-cpm-packages.json') as f:
    after = json.load(f)

def build_map(data):
    m = {}
    for p in data['projects']:
        name = p['path'].split('/')[-1]
        for fw in p['frameworks']:
            for pkg in fw['topLevelPackages']:
                m[(name, fw['framework'], pkg['id'])] = pkg['resolvedVersion']
    return m

b = build_map(baseline)
a = build_map(after)

all_keys = sorted(set(b.keys()) | set(a.keys()))

print('CHANGES:')
for k in all_keys:
    bv = b.get(k, 'N/A')
    av = a.get(k, 'N/A')
    if bv != av:
        print(f'  {k[0]} ({k[1]}): {k[2]}  {bv} -> {av}')

print()
print('UNCHANGED:')
for k in all_keys:
    bv = b.get(k)
    av = a.get(k)
    if bv == av:
        print(f'  {k[0]} ({k[1]}): {k[2]}  {av}')
"", "description": "Compare package versions", "initial_wait": 10}
